raw_response:
resource "aws_lambda_function" "webhook_handler" {
  filename         = "./lambda/handler.zip"
  function_name    = "webhook-handler"
  role            = aws_iam_role.lambda_execution.arn
  handler         = "handler.lambda_handler"
  runtime         = "python3.12"
  timeout         = 30
  memory_size     = 128

  source_code_hash = filebase64sha256("./lambda/handler.py")

  environment {
    variables = {
      LOG_LEVEL = "INFO"
    }
  }

  tracing_config {
    mode = "Active"
  }

  tags = {
    Name        = "webhook-handler"
    Environment = "production"
  }
}

resource "aws_iam_role" "lambda_execution" {
  name = "webhook-handler-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "webhook-handler-lambda-role"
  }
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution.name
}

resource "aws_cloudwatch_log_group" "webhook_handler" {
  name              = "/aws/lambda/${aws_lambda_function.webhook_handler.function_name}"
  retention_in_days = 14

  tags = {
    Environment = "production"
  }
}

